cat > /tmp/varlink_client.pl <<'PERL'
use strict; use warnings; use IO::Socket::UNIX; use JSON::PP;
my $path = shift or die "usage: $0 socket [method [jsonparams]]\n";
my $method = shift // 'org.varlink.service.GetInfo';
my $params = shift // '{}';
my $sock = IO::Socket::UNIX->new(Type => SOCK_STREAM, Peer => $path) or die "connect: $!";
my $req = encode_json({ method => $method, parameters => decode_json($params) }) . "\0";
syswrite($sock, $req) or die "write: $!";
my $buf = '';
while (1) {
    my $chunk = '';
    my $n = sysread($sock, $chunk, 65536);
    last unless defined $n && $n > 0;
    $buf .= $chunk;
    last if index($buf, "\0") >= 0;
}
$buf =~ s/\0.*//s;
print "$buf\n";
PERL
for p in /run/systemd/userdb/io.systemd.DynamicUser /run/systemd/io.systemd.ManagedOOM; do echo "=== $p ==="; timeout 5 perl /tmp/varlink_client.pl "$p" 2>&1; echo "[exit=$?]"; done

